sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, d.name_ar AS dict_name_ar, d.source_type, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('اساس','الاساس','قاعده','القاعده','قاعدة','القاعدة','اسناد','الاسناد','مرتكز','المرتكز','تقوم','التقوم','دعامه','الدعامه') AND (d.source_type = 'ocr' OR (d.source_type = 'hawramani' AND e.definitions_text != '')) ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
# Group by headword_norm
from collections import defaultdict
g=defaultdict(list)
for r in data:
    g[r['headword_norm']].append(r)
for hw,rows in sorted(g.items()):
    print(f'=== {hw} ({len(rows)} entries) ===')
    for r in rows[:5]:
        deftext = r['definitions_text'][:200] if r['definitions_text'] else ''
        print(f'  id={r[\"entry_id\"]} | {r[\"dict_name_ar\"]} | src={r[\"source_type\"]} | root={r[\"root\"]}({r[\"root_source\"]}) | pos={r[\"pos\"]}')
        if deftext: print(f'    def: {deftext}')
        if r['translation_en']: print(f'    en: {r[\"translation_en\"]}')
"
